(async()=>{if(new URLSearchParams(location.search).get('profile')!=='cave-pickaxe-check')return;const wait=ms=>new Promise(r=>setTimeout(r,ms));while(!window.EmberQA)await wait(100);const q=EmberQA,W=EmberTerrain,T=THREE,D=SurvivalData;const panel=document.createElement('section');panel.style='position:fixed;inset:0;z-index:10000;overflow:auto;background:white;color:#234;padding:20px';const report=document.createElement('pre');report.id='report';panel.append(report);document.body.append(panel);document.getElementById('welcome').hidden=true;const results={},check=(k,v)=>{results[k]=!!v;report.textContent=JSON.stringify(results,null,2);if(!v)throw Error(k);};const c=W.caves[0],p=W.cavePoint(c,0,12);q.apply({...D.fresh(),...p,y:W.caveFloor(c,0,12),yaw:Math.atan2(-c.fx,-c.fz),pitch:.15,inventory:{pickaxe:1},hand:'pickaxe',worldTime:360,automaticTime:false,weatherMode:'clear'});q.setPlaying(true);for(let i=0;i<100&&!q.handModel.children.some(g=>g.userData.miningTip&&g.children.some(m=>m.material?.map?.image?.complete));i++)await wait(100);await wait(100);const capture=id=>{q.renderer.render(q.scene,q.camera);const im=document.createElement('img');im.id=id;im.style='width:48%';im.src=q.renderer.domElement.toDataURL();panel.append(im);};capture('cave-fixed');q.inventory();check('inventoryUsesHeldImage',Array.from(document.querySelectorAll('#modalBody img')).some(im=>im.alt.includes('つるはし')&&im.src.endsWith('pickaxe-held.png')));q.close(false);results.hand=q.state.hand;results.art=q.handModel.children.map(g=>({id:g.userData.artId,tip:!!g.userData.miningTip,images:g.children.map(m=>m.material?.map?.image?.src)}));check('generatedHeldTexture',q.handModel.children.some(g=>g.userData.miningTip&&g.children.some(m=>m.material?.map?.image?.src.includes('pickaxe-held.png'))));const ore=q.world.resources.find(r=>r.id.startsWith(c.id+'-')&&r.kind==='ore');check('oreFound',ore);ore.mesh.updateWorldMatrix(true,true);const center=new T.Box3().setFromObject(ore.mesh).getCenter(new T.Vector3());let point=null;for(let i=0;i<16;i++){const x=ore.x+Math.sin(i*Math.PI/8)*2,z=ore.z+Math.cos(i*Math.PI/8)*2,y=W.floor(x,z,ore.y);if(W.inCave(x,z,y)&&!q.world.blocked(x,z,y,q.state)){point={x,z,y};break;}}check('standingPoint',point);Object.assign(q.state,point);q.camera.position.set(point.x,point.y+1.7,point.z);q.camera.lookAt(center);q.camera.rotation.order='YXZ';q.state.yaw=q.camera.rotation.y;q.state.pitch=q.camera.rotation.x;await wait(300);check('aimedOre',q.miningTarget()?.resource===ore);q.camera.rotateY(Math.PI);check('behindPlayerNotTargeted',!q.miningTarget());q.camera.rotateY(-Math.PI);const before=q.state.inventory.ore||0;q.attack();check('noInstantLoot',(q.state.inventory.ore||0)===before);const pose=q.handModel.matrix.clone();q.updateMining(.28);q.handModel.updateMatrix();check('noMiningPoseOverride',pose.equals(q.handModel.matrix));check('lootOnImpact',q.state.inventory.ore===before+3);capture('pickaxe-impact');q.updateMining(.28);check('singleReward',q.state.inventory.ore===before+3);q.handModel.position.set(.42,-.48,-.95);q.handModel.rotation.set(0,0,0);capture('pickaxe-idle');q.apply({...q.snapshot(),depleted:{},inventory:{pickaxe:1}});await wait(150);q.startMining();q.camera.rotateY(Math.PI);q.updateMining(.28);check('turningAwayMisses',!q.state.inventory.ore);results.done=true;report.textContent=JSON.stringify(results,null,2);document.title='洞窟・つるはし検証完了';})().catch(e=>{document.title='Cave pickaxe QA error';document.getElementById('report').textContent+='\n'+e.stack;});
